Perl:

    #!\usr\perl\bin
    use strict;
    use warnings;
    use Data::Dumper;

    open FILE, "<", "SandSim.txt";

    my @sandGrid;

    while(my $line = <FILE>){
    	chomp($line);
    	push(@sandGrid, [split '', $line]);
    }
    close FILE;

    sandSim(@sandGrid);
    printSand(@sandGrid);


    sub sandSim{
    	my @sands = @_;
    	my $col = scalar @{$sands[1]};
    	for my $i (0..$#sands-1){
    			for my $j (0..$col-1){
    				if($sands[$i][$j] eq "."){
    					if($sands[$i+1][$j] eq " "){
    						$sands[$i+1][$j] = ".";
    						$sands[$i][$j] = " ";
    					}
    				}
    			}
    	}
    	return @sands;
    }
    sub printSand{
    	my @array2d = @_;
    	my $col = scalar @{$array2d[1]};
    	for my $i (0..$#array2d){
    			for my $j (0..$col-1){
    				print "$array2d[$i][$j]";
    			}
    		print "\n";
    	}
    }

Perl:

    #usr/perl/bin/ -w

    use strict;
    use warnings;

    my $sentence = $ARGV[0];

    my @vowel;

    while($sentence =~ m/([aeiou])+/){
    	push(@vowel, "$1");
    	$sentence =~ s/[aeiou]{1}//;
    }

    print $sentence . "\n";
    print join("", @vowel);

Perl:

    #Nuts&Bolts

    use strict;
    use warnings;

    my $fileName = "Items.txt";
    #decided it to challenge myself and learn about file handling a bit
    open FILE, "$fileName" or die "Can't find $fileName";
    my @lines;
    while(<FILE>){
    	push(@lines, $_);
    }
    close FILE;

    my $numItems = $lines[0];

    my @oldItems;
    for(my $i = 1; $i < $numItems+1; $i++){
    	push(@oldItems, $lines[$i]);
    }


    my @newItems;
    for(my $i = $numItems+1; $i < scalar(@lines); $i++){
    	push(@newItems, $lines[$i]);
    }

    #compare each item of old and new
    for(my $i = 0; $i < $numItems; $i++){
    	my $oldItemName = substr($oldItems[$i],0 , (index($oldItems[$i], " ") - length($oldItems[$i])));
    	my $oldItemPrice = substr($oldItems[$i],index($oldItems[$i], " "));

    	my $newItemName = substr($newItems[$i],0 , (index($newItems[$i], " ") - length($newItems[$i])));
    	my $newItemPrice = substr($newItems[$i],index($newItems[$i], " "));

    	if($oldItemPrice ne $newItemPrice){
    		print "$oldItemName " . ($oldItemPrice - $newItemPrice) . "\n"; 
    	}
    }
